PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>

SELECT ?italianWord ?count WHERE {
  { SELECT ?italianWord (COUNT(DISTINCT ?sicilianWord) AS ?count) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) ?italianLemma lila:hasPOS lila:noun . }
      FILTER(STRENDS(STR(?italianWord), "ente"))
      ?sicItEntry ontolex:canonicalForm ?italianLemma ; vartrans:translatableAs ?sicEntry .
  ?sicEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ; ontolex:writtenRep ?sicilianWord .
  } GROUP BY ?italianWord }
  { SELECT (MAX(?c) AS ?count) WHERE {
      { SELECT ?italianWord (COUNT(DISTINCT ?sicilianWord) AS ?c) WHERE {
          GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) ?italianLemma lila:hasPOS lila:noun . }
          FILTER(STRENDS(STR(?italianWord), "ente"))
          ?sicItEntry ontolex:canonicalForm ?italianLemma ; vartrans:translatableAs ?sicEntry .
  ?sicEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ; ontolex:writtenRep ?sicilianWord .
      } GROUP BY ?italianWord }
  } }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
