PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>

SELECT ?word ?writtenRep ?count WHERE {
  { SELECT (COUNT(DISTINCT ?refSense) AS ?refCount) WHERE {
      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> { ?ref ontolex:canonicalForm [ ontolex:writtenRep ?refWr ] ; ontolex:sense ?refSense . FILTER(STR(?refWr) = "base") }
  } }
  { SELECT ?word ?writtenRep (COUNT(DISTINCT ?sense) AS ?count) WHERE {
      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?word ontolex:sense ?typedSense . ?typedSense complit:hasSemanticType <http://simpleOntology#94-Act> .
        ?word ontolex:sense ?sense ; ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
      }
  } GROUP BY ?word ?writtenRep }
  FILTER(?count > ?refCount)
}

