PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>

SELECT ?emotion ?emotionLabel ?lemmaCount ?avgPolarity ?withSicilian WHERE {
  { SELECT ?emotion ?emotionLabel (COUNT(DISTINCT ?italianLemma) AS ?lemmaCount) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
      ?emotionEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion ?emotion . ?emotion rdfs:label ?emotionLabel .
  } GROUP BY ?emotion ?emotionLabel }
  { SELECT ?emotion (AVG(?polarityValue) AS ?avgPolarity) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
      ?emotionEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion ?emotion .
      ?polarityEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarityValue ?polarityRaw . BIND(xsd:float(?polarityRaw) AS ?polarityValue)
  } GROUP BY ?emotion }
  { SELECT ?emotion (COUNT(DISTINCT ?italianLemma) AS ?withSicilian) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
      ?emotionEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion ?emotion .
      ?sicItEntry ontolex:canonicalForm ?italianLemma ; vartrans:translatableAs ?sicEntry .
  ?sicEntry ontolex:canonicalForm ?sicilianLemma . ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
  } GROUP BY ?emotion }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
