PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>

SELECT ?pos ?posText ?lemmaCount ?withSicilian ?withParmigiano WHERE {
  { SELECT ?pos (COUNT(DISTINCT ?italianLemma) AS ?lemmaCount) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) ?italianLemma lila:hasPOS ?pos . }
  } GROUP BY ?pos }
  OPTIONAL { SELECT ?pos (COUNT(DISTINCT ?italianLemma) AS ?withSicilian) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) ?italianLemma lila:hasPOS ?pos . }
      ?sicItEntry ontolex:canonicalForm ?italianLemma ; vartrans:translatableAs ?sicEntry .
  ?sicEntry ontolex:canonicalForm ?sicilianLemma . ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
  } GROUP BY ?pos }
  OPTIONAL { SELECT ?pos (COUNT(DISTINCT ?italianLemma) AS ?withParmigiano) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) ?italianLemma lila:hasPOS ?pos . }
      ?parItEntry ontolex:canonicalForm ?italianLemma ; vartrans:translatableAs ?parEntry .
  ?parEntry ontolex:canonicalForm ?parmigianoLemma . ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
  } GROUP BY ?pos }
  BIND(STRAFTER(STR(?pos), "lila/") AS ?posText)
}

