SELECT ?polarity ?lemmaCount ?withEmotion ?withParmigiano WHERE {
  { SELECT ?polarity (COUNT(DISTINCT ?italianLemma) AS ?lemmaCount) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
      ?polarityEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarity ?polarity .
  } GROUP BY ?polarity }
  OPTIONAL { SELECT ?polarity (COUNT(DISTINCT ?italianLemma) AS ?withEmotion) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
      ?polarityEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarity ?polarity .
      ?emotionEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion ?emotion . ?emotion rdfs:label ?emotionLabel .
  } GROUP BY ?polarity }
  OPTIONAL { SELECT ?polarity (COUNT(DISTINCT ?italianLemma) AS ?withParmigiano) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
      ?polarityEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarity ?polarity .
      ?parItEntry ontolex:canonicalForm ?italianLemma ; vartrans:translatableAs ?parEntry .
  ?parEntry ontolex:canonicalForm ?parmigianoLemma . ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
  } GROUP BY ?polarity }
}

