PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>

SELECT ?dialect ?lemmaCount ?linkedLemmas ?italianLemmas WHERE {
  VALUES ?dialect { <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> }
  { SELECT ?dialect (COUNT(DISTINCT ?dLemma) AS ?lemmaCount) WHERE { ?dLemma dcterms:isPartOf ?dialect . } GROUP BY ?dialect }
  { SELECT ?dialect (COUNT(DISTINCT ?dLemma) AS ?linkedLemmas) (COUNT(DISTINCT ?italianLemma) AS ?italianLemmas) WHERE {
      ?dLemma dcterms:isPartOf ?dialect . ?dEntry ontolex:canonicalForm ?dLemma .
      ?itEntry vartrans:translatableAs ?dEntry ; ontolex:canonicalForm ?italianLemma .
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  } GROUP BY ?dialect }
}
